func (c *CLab) Deploy(
	ctx context.Context,
	options *DeployOptions,
) (*DeployResult, error) {
	if options == nil {
		var err error
		options, err = NewDeployOptions(0)
		if err != nil {
			return nil, err
		}
	}

	if options.reconfigure {
		if options.dryRun {
			return nil, fmt.Errorf(
				"dry-run cannot be combined with reconfigure: " +
					"reconfigure always destroys and redeploys the full lab",
			)
		}

		containers, err := c.deploy(ctx, options)
		if err != nil {
			return nil, err
		}

		return &DeployResult{Containers: containers}, nil
	}

	if c.LabRuntime != nil && options.dryRun {
		planner, ok := c.LabRuntime.(clablabruntime.TopologyPlanner)
		if !ok {
			return nil, fmt.Errorf("lab runtime %q does not support dry-run", c.globalRuntimeName)
		}

		req, err := c.labRuntimeDeployRequest()
		if err != nil {
			return nil, err
		}
		applyLabRuntimeDeployOptions(&req, options)

		plan, err := planner.Plan(ctx, req)
		if err != nil {
			return nil, err
		}

		return &DeployResult{RuntimePlan: plan}, nil
	}

	currentNodes, err := c.runtimeNodeGroups(ctx)
	if err != nil {
		return nil, err
	}
	initialDeploy, err := c.needsInitialDeploy(currentNodes)
	if err != nil {
		return nil, err
	}
	if initialDeploy {
		if options.dryRun {
			return &DeployResult{
				Apply: &ApplyResult{
					DryRun:      true,
					DeployedLab: true,
					LabName:     c.Config.Name,
				},
			}, nil
		}

		containers, err := c.deploy(ctx, options)
		if err != nil {
			return nil, err
		}

		return &DeployResult{Containers: containers}, nil
	}

	if err := c.checkReconcileDeployOptions(options); err != nil {
		return nil, err
	}

	applyOptions := &ApplyOptions{
		dryRun:             options.dryRun,
		skipPostDeploy:     options.skipPostDeploy,
		skipLabDirFileACLs: options.skipLabDirFileACLs,
		graph:              options.graph,
		finalizeNoop:       true,
		maxWorkers:         options.maxWorkers,
		exportTemplate:     options.exportTemplate,
	}
	applyResult, err := c.apply(ctx, applyOptions, currentNodes)
	if err != nil {
		return nil, err
	}

	if options.dryRun {
		return &DeployResult{Apply: applyResult}, nil
	}

	containers, err := c.ListNodesContainers(ctx)
	if err != nil {
		return nil, err
	}

	return &DeployResult{Containers: containers, Apply: applyResult}, nil
}

